function largestSquare(grid) {
  const cols = grid[0].length
  let prev = Array(cols + 1).fill(0)
  let best = 0
  for (const row of grid) {
    const cur = Array(cols + 1).fill(0)
    for (let c = 0; c < cols; c++) {
      if (row[c] === 1) {
        cur[c + 1] = 1 + Math.min(prev[c], prev[c + 1], cur[c])
        best = Math.max(best, cur[c + 1])
      }
    }
    prev = cur
  }
  return best * best
}

