def largest_square(grid):
    cols = len(grid[0])
    prev = [0] * (cols + 1)
    best = 0
    for row in grid:
        cur = [0] * (cols + 1)
        for c in range(cols):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                best = max(best, cur[c + 1])
        prev = cur
    return best * best
